<script setup>
import ScreenChart from '@/ScreenChart.vue'
const props=defineProps({state:{type:Object,required:true}})
const {drawer,d,mode,managementUrl,metric,detail,page,loadDemands,eventDetail,label,fmt,sections,openEvent,compareIds,compare,comparison,demands,supply,dynamic,list,evidence,evidencePage,openEvidence,loadEvidence}=props.state
</script>
<template>
<div v-if="drawer" class="shade" :class="{'compare-shade':drawer==='compare'}" @click.self="drawer=''" ><aside class="drawer"><div class="drawer-head"><h2>{{{demands:'诉求明细',event:'事件详情',events:'停供与施工',compare:'网格对比',warnings:'数据预警',research:'冬夏专题研判',analysis:'更多分析',evidence:'专题证据'}[drawer]}}</h2><button @click="drawer=''">关闭 ×</button></div>
<template v-if="drawer==='demands'"><p>统计口径：{{metric}} · {{d.window?.timeBasis}} · {{d.periods?.coverage}}</p><p>共 {{detail?.total ?? '—'}} 条</p><p v-if="mode==='real'">单条诉求的管理端详情跳转协议尚未配置。<a v-if="managementUrl" :href="managementUrl">进入管理后台</a><span v-else>管理后台入口未配置。</span></p><div class="row" v-for="x in detail?.items"><span>{{x.occurredDay}} · {{x.title}}<br>{{label(x.districtCode)}} / {{label(x.communityCode)}} / {{x.categoryCode}}</span><span>{{label(x.businessType)}}<br>{{x.status||'状态未提供'}}</span></div><div><button :disabled="page<=1" @click="page--;loadDemands()">上一页</button> 第 {{page}} 页 <button :disabled="page*10 >= (detail?.total||0)" @click="page++;loadDemands()">下一页</button></div></template>
<template v-if="drawer==='event'"><p>事件历史和相关诉求按来源独立读取，不表示因果关系。</p><h3>{{eventDetail?.event?.title}}</h3><p>类型：{{label(eventDetail?.event?.eventType)}}　审批：{{label(eventDetail?.event?.approvalStatus)}}</p><p>时间：{{eventDetail?.event?.startsAt}} 至 {{eventDetail?.event?.endsAt}}</p><p>企业：{{label(eventDetail?.event?.enterpriseId)}}　影响户数：{{fmt(eventDetail?.event?.households)}}　人员：{{fmt(eventDetail?.event?.workers)}}</p><p>范围：{{eventDetail?.event?.area||'未提供'}}　房屋：{{eventDetail?.event?.housing||'未提供'}}</p><p>原因：{{eventDetail?.event?.reason||'未提供'}}</p><p>预案：{{eventDetail?.event?.plan||'未提供'}}</p><h3>{{eventDetail?.historyNote?'图层版本':'历史修订'}}</h3>
<p v-if="eventDetail?.historyNote">{{eventDetail.historyNote}}</p>
<div class="row" v-for="h in eventDetail?.history">
  <span>版本 {{h.revision??h.sourceRevision??'未提供'}} · {{h.updatedAt??'时间未提供'}}<br>{{h.reason||'原因未提供'}}</span>
  <span>{{label(h.approvalStatus)}}</span>
</div>
<template v-if="eventDetail?.gridHistory?.length">
  <h3>同网格停供历史</h3>
  <div class="row" v-for="previous in eventDetail.gridHistory" :key="previous.id">
    <span>{{previous.title}} · {{previous.id}}<br>{{previous.startsAt}} 至 {{previous.endsAt}}</span>
    <span>{{previous.gridIds.join('、')}}</span>
  </div>
</template>
<h3>相关诉求</h3><p>{{eventDetail?.relatedDemands?.reason}}；{{fmt(eventDetail?.relatedDemands?.total)}} 件</p><p v-for="x in eventDetail?.relatedDemands?.items">{{x.occurredAt}} · {{x.id}} · {{x.type}} · {{label(x.gridId)}}</p></template>
<template v-if="drawer==='events'"><p>计划停水 / 计划停气 / 突发停水 / 突发停气及管线施工</p><button class="row" v-for="e in sections.events" @click="openEvent(e.id)"><span>{{e.title}} · {{label(e.eventType)}}</span><span>{{e.startsAt?.slice(0,10)}} ›</span></button><p v-if="!sections.events?.length">{{d.spatial?.reason||'当前筛选无事件'}}</p></template>
<template v-if="drawer==='compare'"><p>选择 2 至 3 个网格，或点击地图选择。并列最高值同时标记。</p><select multiple v-model="compareIds" size="8"><option v-for="g in sections.grids" :value="g.id" :disabled="compareIds.length>=3&&!compareIds.includes(g.id)">{{g.name}}</option></select><button @click="compare">开始对比</button><p>{{comparison?.provenance}}</p><div class="row" v-for="row in comparison?.rows"><span>{{row.categoryCode}}</span><button v-for="cell in row.values" :class="{active:cell.maximum}" @click="demands('selected',{categoryCode:row.categoryCode,adminGridCode:cell.gridCode})">{{label(cell.gridCode)}}：{{cell.count}}{{cell.maximum?' ★':''}}</button></div></template>
<template v-if="drawer==='warnings'"><p>{{d.warnings?.reason}}</p><button class="row" v-for="w in d.warnings?.data?.items" @click="openEvidence({type:'warning',scenario:w.scenario})"><span>{{{winter:'冬季保供',summer:'夏季保畅',planned:'计划停供',installation:'燃气三件套安装'}[w.scenario]||w.scenario}}</span><span>{{fmt(w.count)}} · {{w.triggered===null?'规则未确认':w.triggered?'触发':'未触发'}}<br>{{w.from}} 至 {{w.to}} · {{fmt(w.days)}} 天 · 阈值 {{fmt(w.threshold)}} · {{w.enabled===null?'启用状态未知':w.enabled?'启用':'停用'}} · {{w.ruleVersion||'版本未提供'}} ›</span></button></template>
<template v-if="drawer==='research'"><p>{{d.research?.reason}}</p><div v-for="season in d.research?.data?.seasons"><h3>{{season.kind==='winter'?'冬季燃气气压':'夏季水压'}}</h3><button class="row" v-for="y in season.years" @click="openEvidence({type:'year',kind:season.kind,year:y.year})">{{y.year}} 季　{{y.from}} 至 {{y.to}}　{{y.count}} 件 ›</button><h4>本期 / 上期月度</h4><div class="row" v-for="m in season.months"><span>{{m.month}} 月</span><button @click="openEvidence({type:'month',kind:season.kind,month:m.month,period:'current'})">本期 {{m.currentCount}}</button><button @click="openEvidence({type:'month',kind:season.kind,month:m.month,period:'previous'})">上期 {{m.previousCount}}</button></div><h4>前六网格同比</h4><div class="row" v-for="g in season.topGrids"><span>{{g.name}}</span><button @click="openEvidence({type:'grid',kind:season.kind,gridCode:g.id,period:'current'})">本期 {{g.count}}</button><button @click="openEvidence({type:'grid',kind:season.kind,gridCode:g.id,period:'previous'})">上期 {{g.previousCount}}</button></div></div></template>
<template v-if="drawer==='evidence'"><p>{{evidence?.reason||'证据使用专题对应窗口及筛选口径'}}</p><p>状态：{{evidence?.state||'加载中'}}　总数：{{fmt(evidence?.total)}}　规则版本：{{evidence?.ruleVersion||'未提供'}}</p><p>窗口：{{evidence?.window?.from||'未提供'}} 至 {{evidence?.window?.to||'未提供'}}　覆盖至 {{evidence?.window?.coverageThrough||'未提供'}}</p><div class="row" v-for="x in evidence?.items"><span>{{x.occurredDay}} · {{x.title}}<br>{{label(x.districtCode)}} / {{label(x.adminGridCode)}} / {{label(x.communityCode)}}</span><span>{{label(x.businessType)}} · {{x.categoryCode}}</span></div><button :disabled="evidencePage<=1" @click="evidencePage--;loadEvidence()">上一页</button> 第 {{evidencePage}} 页 <button :disabled="evidencePage*10 >= (evidence?.total||0)" @click="evidencePage++;loadEvidence()">下一页</button></template>
<template v-if="drawer==='analysis'"><h3>企业每万户</h3><p v-for="x in supply.enterpriseRates">{{x.name||x.id}}：{{fmt(x.per10k)}}　{{x.reason}}　户数 {{fmt(x.households)}}</p><h3>办理时长及分段满意率</h3><p v-for="x in dynamic.duration">{{label(x.key)}}：{{fmt(x.count)}} 件，满意率 {{fmt(x.evaluation?.percent)}}{{x.evaluation?.percent==null?'':'%'}}</p><h3>动态月度变化</h3><div class="analysis-chart"><ScreenChart kind="line" :items="list(dynamic.monthly,'date')"/></div><h3>数据质量</h3><p>重复 {{fmt(d.quality?.duplicates)}} · 缺来源键 {{fmt(d.quality?.missingSourceKey)}} · 缺日期 {{fmt(d.quality?.missingDate)}} · 时间回退 {{fmt(d.quality?.sourceTimeFallback)}}</p><p>生成时间：{{d.generatedAt||'未提供'}}；来源同步与跨源一致性待正式核验。</p></template>
</aside></div>
</template>
